<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          jwks_url</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">https://idp.example.com/.well-known/jwks.json</span></span>
